  Chat: {"title":"Chat/Chat","category":"Chat","displayName":"Chat","description":"Chat is a family of composable primitives for building AI and human chat experiences. Combine ChatLayout, ChatMessageList, ChatMessage, bubbles, system messages, tool calls, tokenized text, and ChatComposer to assemble complete conversations without reimplementing sender-aware layout, density, scrolling, or composer behavior.","hidden":false,"component":"Chat/ChatLayout.astro","demo":"Chat/Chat.demo.astro","subComponents":{"ChatComposer":"Chat/ChatComposer.astro","ChatComposerDrawer":"Chat/ChatComposerDrawer.astro","ChatComposerInput":"Chat/ChatComposerInput.astro","ChatComposerTokenElement":"Chat/ChatComposerTokenElement.astro","ChatLayoutScrollButton":"Chat/ChatLayoutScrollButton.astro","ChatMessage":"Chat/ChatMessage.astro","ChatMessageBubble":"Chat/ChatMessageBubble.astro","ChatMessageList":"Chat/ChatMessageList.astro","ChatMessageMetadata":"Chat/ChatMessageMetadata.astro","ChatSendButton":"Chat/ChatSendButton.astro","ChatSystemMessage":"Chat/ChatSystemMessage.astro","ChatTokenizedText":"Chat/ChatTokenizedText.astro"}},
