  DateRangeInput: {"title":"Form Controls/Date Range Input","category":"Form Controls","displayName":"Date Range Input","description":"DateRangeInput lets users select a start and end date from a dual-month calendar popover. Use it for filtering data by time period, report generation, analytics dashboards, and booking flows.","hidden":false,"component":"DateRangeInput/DateRangeInput.astro","demo":"DateRangeInput/DateRangeInput.demo.astro","subComponents":{}},
  DateTimeInput: {"title":"Form Controls/Date Time Input","category":"Form Controls","displayName":"Date Time Input","description":"DateTimeInput combines date and time selection in one field. With presentation=\"adaptive-native\" (the default), mouse/trackpad devices use Astryx typed fields and popovers, while coarse-pointer devices use browser/OS date and time controls in the same two-segment field. presentation=\"native\" uses both native controls on every pointer; presentation=\"adaptive-bottom-sheet\" keeps Astryx's own surfaces — pointer fields on fine pointers and the coordinated Date/Time bottom sheet on coarse pointers; \"popover\" and \"bottom-sheet\" force one Astryx surface on every pointer. The closed segments stay side by side when at least 400px is available and wrap into full-width rows below 400px, independent of viewport width. Use it for scheduling, event creation, deadline setting, or any form field that needs a specific datetime.","hidden":false,"component":"DateTimeInput/DateTimeInput.astro","demo":"DateTimeInput/DateTimeInput.demo.astro","subComponents":{}},
  Dialog: {"title":"Overlay/Dialog","category":"Overlay","displayName":"Dialog","description":"Modal dialog using the native <dialog> element. Modal and inline content starts with theme body text defaults. Ancestor surface/group membership ends as a whole, including group-owned state. Explicit props and unrelated contexts remain unchanged. Place intentional groups and complete required providers inside the dialog. With reduced motion the dialog never slides or scales in: on a touch screen it fades in, in 200 ms or less, and with a mouse it appears at once. On a phone or tablet (a coarse primary pointer), a tap or a drag that lands while the dialog is still entering reaches nothing, and the dialog finishes entering; keys and assistive technology stay live, and a mouse or a trackpad still clicks: at once when it was the last pointer used, otherwise once it moves.","hidden":false,"component":"Dialog/Dialog.astro","demo":"Dialog/Dialog.demo.astro","subComponents":{"DialogHeader":"Dialog/DialogHeader.astro"}},
