  Indicator: {"title":"Form Controls/Indicator","category":"Form Controls","displayName":"Indicator","description":"Decorative control visuals: the mark on a chosen option, the box a checkbox draws, the circle a radio draws. Rendered by Selector, CheckboxInput, RadioList, and menu selection rows. Replace one by name through defineTheme({indicators}) and every component drawing it follows.","hidden":true,"component":"Indicator/Indicator.astro","demo":"Indicator/Indicator.demo.astro","subComponents":{}},
  InfoTip: {"title":"Feedback & Status/Info Tip","category":"Feedback & Status","displayName":"Info Tip","description":"An info icon that reveals help: a small \"i\" button. Hover and keyboard focus preview the help, and a click, tap, Enter, or Space pins it open until Escape, a second press, a press outside, or focus leaving. Use it next to labels, values, and metrics for permission notes, metric definitions, and field help. Its value over hand-composing Icon inside Tooltip is the pre-wired accessible trigger: a real button with an aria-label, Tab-reachable, tooltip on hover AND focus AND tap, and Escape dismissal. It follows the toggletip pattern: the button reports `aria-expanded=\"true\"` while the help is pinned, and a screen reader hears the help once when it pins.","hidden":false,"component":"InfoTip/InfoTip.astro","demo":"InfoTip/InfoTip.demo.astro","subComponents":{}},
